package main

import (
	"fmt"
	"slices"
	"strconv"
	"strings"

	"calyx/sdktools/internal/spec"
)

const header = "<?php\n\n// Generated by phpgen. Do not edit.\n\ndeclare(strict_types=1);\n\n"

// buildFiles checks the PHP names and returns the generated files by their path in the
// Generated folder.
func buildFiles(doc *spec.Doc) (map[string][]byte, error) {
	rows, ops := doc.Advice, doc.Operations
	if err := checkAdvice(rows); err != nil {
		return nil, err
	}
	var roots []*spec.Schema
	for _, op := range ops {
		roots = append(roots, op.Request, op.Answer)
	}
	for _, e := range doc.PairingEvents {
		roots = append(roots, e.Data)
	}
	names, err := doc.UsedBy(roots...)
	if err != nil {
		return nil, err
	}
	files := map[string][]byte{
		"BackendCode.php": codeFile("backend", "The backend codes: the Problem.code enum of backend.json.", rows),
		"CoreCode.php":    codeFile("core", "The core codes: the ErrorReason names and the gRPC status names.", rows),
		"ClientCode.php":  codeFile("client", "The client codes of CONTRACT.md part 5, and the PHP client codes.", rows),
		"Advice.php":      adviceFile(rows),
		"Operations.php":  operationsFile(ops),
	}
	classes := map[string]string{}
	for _, name := range names {
		class, err := className(name)
		if err != nil {
			return nil, err
		}
		if other, ok := classes[strings.ToLower(class)]; ok {
			return nil, fmt.Errorf("the schemas %s and %s have the same class name %s", other, name, class)
		}
		classes[strings.ToLower(class)] = name
		content, err := modelFile(name, class, doc.Schemas[name])
		if err != nil {
			return nil, err
		}
		files["Model/"+class+".php"] = content
	}
	return files, nil
}

// phpString writes s as a single-quoted PHP string.
func phpString(s string) string {
	return "'" + strings.NewReplacer(`\`, `\\`, `'`, `\'`).Replace(s) + "'"
}

func codeFile(source, doc string, rows []spec.AdviceRow) []byte {
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("namespace Calyx\\Client\\Generated;\n\n")
	fmt.Fprintf(&b, "/** %s */\nfinal class %s\n{\n", doc, codeClasses[source])
	var codes []string
	for _, r := range rows {
		if r.Source == source {
			codes = append(codes, r.Code)
		}
	}
	if source == "client" {
		codes = append(codes, phpOnlyClientCodes...)
	}
	for _, code := range codes {
		fmt.Fprintf(&b, "    public const string %s = %s;\n", codeConstant(code), phpString(code))
	}
	b.WriteString("}\n")
	return []byte(b.String())
}

func adviceFile(rows []spec.AdviceRow) []byte {
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("namespace Calyx\\Client\\Generated;\n\nuse Calyx\\Client\\RetryAdvice;\n\n")
	b.WriteString("/** The retry advice of packages/client-sdk/testdata/retry-advice.json, by source and code. */\n")
	b.WriteString("final class Advice\n{\n")
	b.WriteString("    /** @var array<string, array<string, RetryAdvice>> */\n")
	b.WriteString("    public const array MAP = [\n")
	for _, source := range spec.Sources {
		fmt.Fprintf(&b, "        %s => [\n", phpString(source))
		for _, r := range rows {
			if r.Source == source {
				fmt.Fprintf(&b, "            %s => RetryAdvice::%s,\n", phpString(r.Code), retryCases[r.Retry])
			}
		}
		b.WriteString("        ],\n")
	}
	b.WriteString("    ];\n}\n")
	return []byte(b.String())
}

func operationsFile(ops []spec.Operation) []byte {
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("namespace Calyx\\Client\\Generated;\n\n")
	b.WriteString("/**\n")
	b.WriteString(" * The included operations of CONTRACT.md part 2: the HTTP method, the path, the default time\n")
	b.WriteString(" * limit in seconds (null for no limit) and the idempotency key flag.\n")
	b.WriteString(" */\n")
	b.WriteString("final class Operations\n{\n")
	b.WriteString("    /** @var array<string, array{method: string, path: string, timeLimit: ?float, idempotencyKey: bool}> */\n")
	b.WriteString("    public const array ALL = [\n")
	for _, op := range ops {
		limit := "null"
		if op.TimeLimit > 0 {
			limit = strconv.Itoa(op.TimeLimit) + ".0"
		}
		fmt.Fprintf(&b, "        %s => ['method' => %s, 'path' => %s, 'timeLimit' => %s, 'idempotencyKey' => %t],\n",
			phpString(op.ID), phpString(op.Method), phpString(op.Path), limit, op.IdempotencyKey)
	}
	b.WriteString("    ];\n}\n")
	return []byte(b.String())
}

// field is one property of a model class.
type field struct {
	Wire string
	Name string
	// PHPType is the declared type, DocType the PHPStan type when it says more ("" if not).
	PHPType string
	DocType string
	// HasDefault tells if the constructor parameter has the default null.
	HasDefault bool
	// Reader reads the field from the FieldReader $r; Writer gives its wire value.
	Reader string
	Writer string
	Enum   []string
}

// propertyName turns a wire name into a camelCase property name, for example message_id
// into messageId.
func propertyName(wire string) string {
	parts := strings.Split(wire, "_")
	for i := 1; i < len(parts); i++ {
		if parts[i] != "" {
			parts[i] = strings.ToUpper(parts[i][:1]) + parts[i][1:]
		}
	}
	return strings.Join(parts, "")
}

// refClass returns the class name of the schema name. The rename table applies; the clash
// check runs when the class of the schema itself is written.
func refClass(name string) string {
	if renamed, ok := renames[name]; ok {
		return renamed
	}
	return name
}

var scalarTypes = map[string]string{"string": "string", "integer": "int", "number": "float", "boolean": "bool"}

// newField maps one property to PHP with the type map scalarTypes.
func newField(schema, wire string, s *spec.Schema, required bool) (field, error) {
	f := field{Wire: wire, Name: propertyName(wire)}
	nullable := !required || s.Nullable
	var base, item string // base: the PHP type without "?"; item: the class or type of a list item
	kind := ""
	switch {
	case s.Ref != "":
		kind, base = "object", refClass(s.Ref)
	case len(s.OneOf) == 2 && s.OneOf[0].Ref != "" && s.OneOf[1].Type == "null":
		kind, base = "object", refClass(s.OneOf[0].Ref)
	case s.Type == "array" && s.Items != nil && s.Items.Ref != "":
		kind, base, item = "list", "array", refClass(s.Items.Ref)
	case s.Type == "array" && s.Items != nil && s.Items.Type == "string" && !s.Items.Nullable:
		kind, base, item = "stringList", "array", "string"
	case s.Type == "" && s.Ref == "" && len(s.OneOf) == 0 && s.Items == nil && s.Properties == nil &&
		s.AdditionalProperties == nil && len(s.Enum) == 0:
		kind, base = "mixed", "mixed"
	default:
		base = scalarTypes[s.Type]
		kind = base
	}
	if base == "" {
		return field{}, fmt.Errorf("the property %s.%s has a type that phpgen does not support", schema, wire)
	}

	f.PHPType = base
	if nullable && base != "mixed" {
		f.PHPType = "?" + base
	}
	f.HasDefault = nullable && (base != "mixed" || !required)
	if item != "" {
		f.DocType = "list<" + item + ">"
	}

	method := kind
	if nullable && kind != "mixed" {
		method += "OrNull"
	}
	args := []string{phpString(wire)}
	switch kind {
	case "object":
		args = append(args, base+"::fromArray(...)")
	case "list":
		args = append(args, item+"::fromArray(...)")
	}
	if required && (nullable || kind == "mixed") {
		args = append(args, "required: true")
	}
	f.Reader = "$r->" + method + "(" + strings.Join(args, ", ") + ")"

	value := "$this->" + f.Name
	switch {
	case kind == "object" && nullable:
		f.Writer = value + "?->toArray()"
	case kind == "object":
		f.Writer = value + "->toArray()"
	case kind == "list":
		f.Writer = fmt.Sprintf("array_map(static fn(%s $item): array => $item->toArray(), %s)", item, value)
		if nullable {
			f.Writer = value + " === null ? null : " + f.Writer
		}
	default:
		f.Writer = value
	}

	for _, v := range s.Enum {
		if v != nil {
			f.Enum = append(f.Enum, *v)
		}
	}
	return f, nil
}

// modelFields returns the fields in constructor order: the fields without a default first,
// each group in the order of the properties of the schema.
func modelFields(name string, s *spec.Schema) ([]field, error) {
	var first, last []field
	names := map[string]bool{}
	for _, p := range s.Properties {
		if !wirePattern.MatchString(p.Name) {
			return nil, fmt.Errorf("the property %s.%s cannot be a PHP property name", name, p.Name)
		}
		f, err := newField(name, p.Name, p.Schema, p.Required)
		if err != nil {
			return nil, err
		}
		if names[f.Name] {
			return nil, fmt.Errorf("two properties of %s have the PHP name %s", name, f.Name)
		}
		names[f.Name] = true
		if f.HasDefault {
			last = append(last, f)
		} else {
			first = append(first, f)
		}
	}
	return append(first, last...), nil
}

func modelFile(name, class string, s *spec.Schema) ([]byte, error) {
	fields, err := modelFields(name, s)
	if err != nil {
		return nil, err
	}
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("namespace Calyx\\Client\\Generated\\Model;\n\n")
	b.WriteString("use Calyx\\Client\\CalyxException;\nuse Calyx\\Client\\Internal\\FieldReader;\nuse JsonSerializable;\n\n")
	fmt.Fprintf(&b, "/** The schema %s of backend.json. */\n", name)
	fmt.Fprintf(&b, "final readonly class %s implements JsonSerializable\n{\n", class)
	fmt.Fprintf(&b, "    public const string SCHEMA = %s;\n\n", phpString(name))

	b.WriteString("    /** The wire name of each property. */\n")
	b.WriteString("    public const array WIRE_NAMES = [")
	if len(fields) > 0 {
		b.WriteString("\n")
		for _, f := range fields {
			fmt.Fprintf(&b, "        %s => %s,\n", phpString(f.Name), phpString(f.Wire))
		}
		b.WriteString("    ")
	}
	b.WriteString("];\n")

	constants := map[string]bool{"SCHEMA": true, "WIRE_NAMES": true}
	for _, f := range fields {
		if len(f.Enum) == 0 {
			continue
		}
		b.WriteString("\n")
		for _, v := range f.Enum {
			c := strings.ToUpper(f.Wire + "_" + v)
			if !constantPattern.MatchString(c) || constants[c] {
				return nil, fmt.Errorf("the enum value %q of %s.%s gives no unique PHP constant name", v, name, f.Wire)
			}
			constants[c] = true
			fmt.Fprintf(&b, "    public const string %s = %s;\n", c, phpString(v))
		}
	}

	b.WriteString("\n")
	var docs []string
	for _, f := range fields {
		if f.DocType != "" {
			t := f.DocType
			if strings.HasPrefix(f.PHPType, "?") {
				t += "|null"
			}
			docs = append(docs, fmt.Sprintf("     * @param %s $%s\n", t, f.Name))
		}
	}
	if len(docs) > 0 {
		b.WriteString("    /**\n" + strings.Join(docs, "") + "     */\n")
	}
	if len(fields) == 0 {
		b.WriteString("    public function __construct() {}\n")
	} else {
		b.WriteString("    public function __construct(\n")
		for _, f := range fields {
			def := ""
			if f.HasDefault {
				def = " = null"
			}
			fmt.Fprintf(&b, "        public %s $%s%s,\n", f.PHPType, f.Name, def)
		}
		b.WriteString("    ) {}\n")
	}

	b.WriteString("\n    /**\n")
	b.WriteString("     * @param array<mixed> $data\n")
	b.WriteString("     *\n")
	b.WriteString("     * @throws CalyxException invalid_response, when a required field is missing or a field has\n")
	b.WriteString("     *                        the wrong JSON type\n")
	b.WriteString("     */\n")
	b.WriteString("    public static function fromArray(array $data): self\n    {\n")
	if len(fields) == 0 {
		b.WriteString("        return new self();\n")
	} else {
		fmt.Fprintf(&b, "        $r = new FieldReader(%s, $data);\n\n", phpString(name))
		b.WriteString("        return new self(\n")
		for _, f := range fields {
			fmt.Fprintf(&b, "            %s: %s,\n", f.Name, f.Reader)
		}
		b.WriteString("        );\n")
	}
	b.WriteString("    }\n")

	b.WriteString("\n    /** @return array<string, mixed> */\n")
	b.WriteString("    public function toArray(): array\n    {\n")
	// array_filter only when a value can be null: PHPStan reports a check that is always true.
	canBeNull := slices.ContainsFunc(fields, func(f field) bool {
		return strings.HasPrefix(f.PHPType, "?") || f.PHPType == "mixed"
	})
	if canBeNull {
		b.WriteString("        return array_filter([\n")
	} else {
		b.WriteString("        return [")
		if len(fields) > 0 {
			b.WriteString("\n")
		}
	}
	for _, f := range fields {
		fmt.Fprintf(&b, "            %s => %s,\n", phpString(f.Wire), f.Writer)
	}
	switch {
	case canBeNull:
		b.WriteString("        ], static fn(mixed $value): bool => $value !== null);\n")
	case len(fields) > 0:
		b.WriteString("        ];\n")
	default:
		b.WriteString("];\n")
	}
	b.WriteString("    }\n")

	// json_encode() writes an empty PHP array as [], so the wire form is an object at every
	// depth: nested models stay models, and an empty list stays [].
	b.WriteString("\n    public function jsonSerialize(): object\n    {\n")
	if canBeNull {
		b.WriteString("        return (object) array_filter([\n")
	} else {
		b.WriteString("        return (object) [")
		if len(fields) > 0 {
			b.WriteString("\n")
		}
	}
	for _, f := range fields {
		fmt.Fprintf(&b, "            %s => $this->%s,\n", phpString(f.Wire), f.Name)
	}
	switch {
	case canBeNull:
		b.WriteString("        ], static fn(mixed $value): bool => $value !== null);\n")
	case len(fields) > 0:
		b.WriteString("        ];\n")
	default:
		b.WriteString("];\n")
	}
	b.WriteString("    }\n}\n")
	return []byte(b.String()), nil
}
